PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY, name TEXT NOT NULL, email TEXT NOT NULL UNIQUE COLLATE NOCASE, password TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('admin','teacher','student')), phone TEXT NOT NULL DEFAULT '', active INTEGER NOT NULL DEFAULT 1, created TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS teachers(user_id INTEGER PRIMARY KEY REFERENCES users(id), specialty TEXT NOT NULL, registration TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS membership_plans(id INTEGER PRIMARY KEY, name TEXT NOT NULL UNIQUE, description TEXT NOT NULL, price REAL NOT NULL CHECK(price>=0), months INTEGER NOT NULL CHECK(months>0), benefits TEXT NOT NULL, active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS students(user_id INTEGER PRIMARY KEY REFERENCES users(id), teacher_id INTEGER REFERENCES teachers(user_id), birthday TEXT, enrollment TEXT NOT NULL, objective TEXT NOT NULL DEFAULT '', consent INTEGER NOT NULL DEFAULT 0);
CREATE INDEX IF NOT EXISTS student_teacher ON students(teacher_id);
CREATE TABLE IF NOT EXISTS subscriptions(id INTEGER PRIMARY KEY, student_id INTEGER NOT NULL REFERENCES students(user_id), plan_id INTEGER NOT NULL REFERENCES membership_plans(id), start TEXT NOT NULL, active INTEGER NOT NULL DEFAULT 1);
CREATE UNIQUE INDEX IF NOT EXISTS one_active_subscription ON subscriptions(student_id) WHERE active=1;
CREATE TABLE IF NOT EXISTS exercises(id INTEGER PRIMARY KEY, name TEXT NOT NULL, muscle TEXT NOT NULL, equipment TEXT NOT NULL, level TEXT NOT NULL, instructions TEXT NOT NULL, precautions TEXT NOT NULL DEFAULT '', active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS workouts(id INTEGER PRIMARY KEY, student_id INTEGER NOT NULL REFERENCES students(user_id), teacher_id INTEGER NOT NULL REFERENCES users(id), name TEXT NOT NULL, objective TEXT NOT NULL, division TEXT NOT NULL, notes TEXT NOT NULL DEFAULT '', created TEXT NOT NULL, updated TEXT NOT NULL, active INTEGER NOT NULL DEFAULT 1);
CREATE INDEX IF NOT EXISTS workout_student ON workouts(student_id);
CREATE TABLE IF NOT EXISTS workout_exercises(id INTEGER PRIMARY KEY, workout_id INTEGER NOT NULL REFERENCES workouts(id), exercise_id INTEGER NOT NULL REFERENCES exercises(id), position INTEGER NOT NULL, sets INTEGER NOT NULL CHECK(sets>0), reps TEXT NOT NULL, load REAL NOT NULL CHECK(load>=0), rest INTEGER NOT NULL CHECK(rest>=0));
CREATE TABLE IF NOT EXISTS workout_versions(id INTEGER PRIMARY KEY, workout_id INTEGER NOT NULL REFERENCES workouts(id), snapshot TEXT NOT NULL, created TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS workout_sessions(id INTEGER PRIMARY KEY, workout_id INTEGER NOT NULL REFERENCES workouts(id), student_id INTEGER NOT NULL REFERENCES students(user_id), created TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS workout_logs(id INTEGER PRIMARY KEY, session_id INTEGER NOT NULL REFERENCES workout_sessions(id), exercise_id INTEGER NOT NULL REFERENCES exercises(id), name TEXT NOT NULL, sets INTEGER NOT NULL, reps INTEGER NOT NULL CHECK(reps>0), load REAL NOT NULL CHECK(load>=0));
CREATE TABLE IF NOT EXISTS assessments(id INTEGER PRIMARY KEY, student_id INTEGER NOT NULL REFERENCES students(user_id), teacher_id INTEGER NOT NULL REFERENCES users(id), date TEXT NOT NULL, weight REAL NOT NULL CHECK(weight>0), height REAL NOT NULL CHECK(height>0), waist REAL NOT NULL CHECK(waist>0), notes TEXT NOT NULL, objective TEXT NOT NULL, next_date TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS assessment_student ON assessments(student_id,date);
CREATE TABLE IF NOT EXISTS attendance(id INTEGER PRIMARY KEY, student_id INTEGER NOT NULL REFERENCES students(user_id), day TEXT NOT NULL, time TEXT NOT NULL, actor_id INTEGER NOT NULL REFERENCES users(id), UNIQUE(student_id,day));
CREATE TABLE IF NOT EXISTS payments(id INTEGER PRIMARY KEY, student_id INTEGER NOT NULL REFERENCES students(user_id), subscription_id INTEGER NOT NULL REFERENCES subscriptions(id), amount REAL NOT NULL CHECK(amount>=0), due TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('Pendente','Pago','Cancelado')), paid_at TEXT, method TEXT NOT NULL DEFAULT '');
CREATE INDEX IF NOT EXISTS payment_due ON payments(due,status);
CREATE TABLE IF NOT EXISTS sessions(token TEXT PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES users(id), csrf TEXT NOT NULL, expires REAL NOT NULL);
CREATE TABLE IF NOT EXISTS notifications(id INTEGER PRIMARY KEY, user_id INTEGER REFERENCES users(id), title TEXT NOT NULL, created TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS audit_logs(id INTEGER PRIMARY KEY, actor_id INTEGER NOT NULL REFERENCES users(id), action TEXT NOT NULL, entity TEXT NOT NULL, entity_id INTEGER, created TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS settings(id INTEGER PRIMARY KEY CHECK(id=1), gym_name TEXT NOT NULL DEFAULT 'GymFlow Studio', phone TEXT NOT NULL DEFAULT '', address TEXT NOT NULL DEFAULT '');
INSERT OR IGNORE INTO settings(id) VALUES(1);
PRAGMA user_version=1;
